import math
from fractions import Fraction

from frontdoor.ratelimit.address import client_address, in_any, key_text
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = list(config.section("limit") or [])
        self.trusted = tuple(config.section("clients") or ())
        self.states = [{} for _ in self.limits]
        self.limited = {lim.name: 0 for lim in self.limits}
        self.now = None


def setup(config):
    return State(config)


def _part(part, ctx, client):
    if part == "tenant":
        return ctx.tenant
    if part == "client":
        return key_text(client)
    if part == "route":
        return ctx.route.name
    if part == "method":
        return ctx.request.method
    value = ctx.request.headers.get(part[len("header:"):])
    if value is None:
        return None
    return value.strip(" \t") or None


def _covering(state, ctx, client):
    """The (index, limit, key) of every limit covering the request."""
    out = []
    for i, lim in enumerate(state.limits):
        if lim.routes is not None and ctx.route.name not in lim.routes:
            continue
        if lim.methods is not None and ctx.request.method not in lim.methods:
            continue
        key = tuple(_part(p, ctx, client) for p in lim.key)
        if any(v is None for v in key):
            continue
        if not isinstance(client, str) and in_any(client, lim.exempt):
            continue
        out.append((i, lim, key))
    return out


def handle(ctx, state):
    if not state.limits:
        return None
    ts = ctx.request.ts_ms
    state.now = ts if state.now is None else max(state.now, ts)
    now = state.now
    client = client_address(ctx.request, state.trusted)
    covering = _covering(state, ctx, client)
    if not covering:
        return None
    method = ctx.request.method
    checks = []
    for i, lim, key in covering:
        table = state.states[i]
        s = table.get(key)
        if s is None:
            s = table[key] = new_state(lim, now)
        s.refill(now)
        cost = lim.cost_of(method)
        over = cost > lim.capacity
        checks.append((lim, s, cost, over, (not over) and s.allows(cost)))

    if all(c[4] for c in checks):
        for lim, s, cost, _, _ in checks:
            s.charge(cost)
        best = None
        for lim, s, cost, _, _ in checks:
            rem = s.remaining()
            if best is None or rem < best[0]:
                best = (rem, lim, s)
        _, lim, s = best
        ctx.headers["RateLimit-Limit"] = str(lim.capacity)
        ctx.headers["RateLimit-Remaining"] = str(s.remaining())
        ctx.headers["RateLimit-Reset"] = str(s.reset(now))
        return None

    deciding = None
    for lim, s, cost, over, ok in checks:
        if ok:
            continue
        state.limited[lim.name] += 1
        wait = None if over else s.wait(cost, now)
        if deciding is None:
            deciding = (lim, s, cost, wait)
        else:
            cur = deciding[3]
            longer = (cur is not None) and (wait is None or wait > cur)
            if longer:
                deciding = (lim, s, cost, wait)
    lim, s, cost, wait = deciding
    ctx.headers["RateLimit-Limit"] = str(lim.capacity)
    ctx.headers["RateLimit-Remaining"] = str(s.remaining())
    ctx.headers["RateLimit-Reset"] = str(s.reset(now))
    if wait is not None:
        ctx.headers["Retry-After"] = str(max(1, math.ceil(Fraction(wait) / 1000)))
    return 429


def summary(state):
    if not state.limits:
        return {}
    return {"limited": dict(state.limited)}
