    ctx.headers["RateLimit-Limit"] = str(lim.capacity)
    ctx.headers["RateLimit-Remaining"] = str(s.remaining())
    ctx.headers["RateLimit-Reset"] = str(s.reset(now))
    if wait is not None:
        ctx.headers["Retry-After"] = str(max(1, math.ceil(Fraction(wait) / 1000)))
    return 429


def summary(state):
    if not state.limits:
        return {}
    return {"limited": dict(state.limited)}
